#!/data/data/com.termux/files/usr/bin/bash
# ================================================================
# AB-210-TRQ — المثبّت الذهبي (ملف واحد يحتوي كل شيء)
# لا يحتاج أي تحميل إضافي — السيرفر مضمّن بالكامل بداخله
# منسّق + 5 محركات | حارس ذاتي | إقلاع تلقائي بعد إعادة التشغيل
# ================================================================
echo "═══ AB-210-TRQ — التثبيت الكامل ═══"
echo "التاريخ: $(date '+%F %T')"

if [ ! -d "/data/data/com.termux" ]; then
  echo "✗ هذا السكربت مخصص لـ Termux فقط"
  exit 1
fi
if ! command -v node >/dev/null 2>&1; then
  echo "• تثبيت Node.js..."
  pkg install nodejs -y
fi
NM=$(node -v 2>/dev/null | sed 's/v\([0-9]*\).*/\1/')
if [ "${NM:-0}" -lt 18 ]; then
  echo "✗ إصدار Node قديم ($(node -v 2>/dev/null)) — نفّذ: pkg upgrade -y && pkg install nodejs -y ثم أعد المحاولة"
  exit 1
fi
echo "✓ Node $(node -v)"

echo "• فكّ السيرفر المضمّن (لا اتصال خارجي)..."
base64 -d <<'TRGB64' > ~/trg-server.mjs 2>/dev/null || { echo "✗ فشل فك الملف"; exit 1; }
