if ! node --check ~/trg-server.mjs >/dev/null 2>&1; then
  echo "✗ الملف المفكوكة تالف — أعد تشغيل الأمر"
  exit 1
fi
echo "✓ السيرفر مثبت: $(grep -o 'AB-210-TRQ-[0-9.]*' ~/trg-server.mjs | head -1) ($(wc -c < ~/trg-server.mjs) بايت)"

command -v termux-wake-lock >/dev/null 2>&1 && termux-wake-lock 2>/dev/null && echo "✓ قفل اليقظة مفعّل"

echo "• إيقاف أي نسخة قديمة..."
pkill -f trg-server.mjs 2>/dev/null; sleep 2; pkill -9 -f trg-server.mjs 2>/dev/null; sleep 1
for port in 9010 9011 9012 9013 9014 9015; do
  curl -fs --max-time 2 "127.0.0.1:$port/health" >/dev/null 2>&1 && { command -v fuser >/dev/null 2>&1 && fuser -k "$port/tcp" 2>/dev/null; sleep 1; }
done

[ -f ~/trg-server.log ] && [ "$(wc -c < ~/trg-server.log)" -gt 5000000 ] && { tail -n 2000 ~/trg-server.log > ~/trg-server.log.t && mv ~/trg-server.log.t ~/trg-server.log; }

echo "• انطلاق الأسطول (منسّق + 5 محركات)..."
nohup node ~/trg-server.mjs >> ~/trg-server.log 2>&1 &

OK=""
for i in $(seq 1 20); do
  sleep 3
  curl -fs --max-time 4 "127.0.0.1:9010/health" >/dev/null 2>&1 && { OK=1; break; }
done
if [ -z "$OK" ]; then
  echo ""
  echo "✗ المنسّق لم يستجب خلال 60 ثانية — آخر 15 سطرًا من السجل:"
  tail -n 15 ~/trg-server.log 2>/dev/null
  echo "── صوّر هذه الشاشة وأرسلها ──"
  exit 1
fi
echo "✓ المنسّق يعمل على 9010"
sleep 4
ENGINES=0
for p in 9011 9012 9013 9014 9015; do
  curl -fs --max-time 4 "127.0.0.1:$p/health" >/dev/null 2>&1 && ENGINES=$((ENGINES+1))
done
echo "✓ $ENGINES/5 محركات حية"

echo "• فحص البقاء 40 ثانية (لا تغلق Termux ولا تطفئ الشاشة)..."
SURVIVED=1
for i in $(seq 1 8); do
  sleep 5
  curl -fs --max-time 3 "127.0.0.1:9010/health" >/dev/null 2>&1 || { SURVIVED=""; break; }
done

cat > ~/trg-watchdog.sh <<'WD'
#!/data/data/com.termux/files/usr/bin/bash
while true; do
  if ! curl -fs --max-time 8 127.0.0.1:9010/health >/dev/null 2>&1; then
    echo "[$(date '+%F %T')] أسطول AB-210-TRQ لا يرد — إعادة تشغيل" >> ~/trg-watchdog.log
    termux-wake-lock 2>/dev/null
    pgrep -f trg-server.mjs >/dev/null 2>&1 && pkill -f trg-server.mjs
    sleep 2
    nohup node ~/trg-server.mjs >> ~/trg-server.log 2>&1 &
  else
    termux-wake-lock 2>/dev/null
  fi
  sleep 60
done
WD
chmod +x ~/trg-watchdog.sh
pgrep -f trg-watchdog.sh >/dev/null 2>&1 && pkill -f trg-watchdog.sh
nohup bash ~/trg-watchdog.sh >/dev/null 2>&1 &
echo "✓ الحارس الذاتي يعمل (فحص كل 60 ثانية)"

mkdir -p ~/.termux/boot
cat > ~/.termux/boot/trg.sh <<'BT'
#!/data/data/com.termux/files/usr/bin/bash
termux-wake-lock 2>/dev/null || true
if ! pgrep -f trg-server.mjs >/dev/null 2>&1; then
  nohup node ~/trg-server.mjs >> ~/trg-server.log 2>&1 &
fi
if ! pgrep -f trg-watchdog.sh >/dev/null 2>&1; then
  nohup bash ~/trg-watchdog.sh >/dev/null 2>&1 &
fi
BT
chmod +x ~/.termux/boot/trg.sh
echo "✓ الإقلاع التلقائي مُجهّز (ثبّت تطبيق Termux:Boot وافتحه مرة إن لم يكن مثبتًا)"

ENGINES2=0
for p in 9011 9012 9013 9014 9015; do
  curl -fs --max-time 3 "127.0.0.1:$p/health" >/dev/null 2>&1 && ENGINES2=$((ENGINES2+1))
done

echo ""
echo "═════════════════════════════════════════"
if [ "$SURVIVED" = "1" ]; then
  echo "النتيجة النهائية: ✓ الأسطول يعمل وثابت ($ENGINES2/5 محركات)"
  echo "افتح تطبيق AB-210-TRQ الآن وانتظر 15 ثانية — ستظهر حبة «سيرفر»"
else
  echo "النتيجة النهائية: ✗ انطفأ خلال فحص البقاء — صوّر هذه الشاشة"
  tail -n 15 ~/trg-server.log 2>/dev/null
fi
echo "═════════════════════════════════════════"
echo "لإبقائه 24 ساعة (مهم جدًا):"
echo "  1) اسحب إشعار Termux ← اضغط Acquire WakeLock"
echo "  2) إعدادات ← تطبيقات ← Termux ← البطارية ← «غير مقيّد»"
echo "  3) إعدادات ← تطبيقات ← AB-210-TRQ ← البطارية ← «غير مقيّد»"
echo "  4) لا تسحب Termux من التطبيقات الأخيرة أبدًا"
